/**
 * ESI.ts is a library of hand-written custom clients (guides/CHARTER.md,
 * Part 1, and guides/CLIENT-ARCHITECTURE.md). Generation serves them; it
 * never replaces them. ARCH-14 makes that a gate: a change that deprecates or
 * removes a custom-client construction surface, or swaps one for the
 * generated surface, fails here before it can merge.
 *
 * The cases read the API report (`etc/esi.ts.api.md`, regenerated by
 * `npm run api-report`) for what a consumer sees, the source for the
 * `@deprecated` tags an editor shows, and the client registry at runtime for
 * the domain clients `EsiClientBuilder` and `EsiApiFactory.createClient` hand
 * out. The nine named `EsiApiFactory.create*Client` methods and
 * `EsiTokenManager.createClient` stay deprecated (since 11.0.0) in favour of
 * `createClient(type)` and the builder; they are not on the list.
 */
import { readFileSync, readdirSync } from 'fs';
import * as path from 'path';
import * as root from '../../../src';
import { ApiClient } from '../../../src/core/ApiClient';
import {
  ApiClientType,
  createClientInstance,
} from '../../../src/clients/ClientRegistry';
import { BaseEsiClient } from '../../../src/clients/BaseEsiClient';

const ROOT = path.resolve(__dirname, '../../..');
const read = (rel: string): string =>
  readFileSync(path.join(ROOT, rel), 'utf8');
const reportLines = read('etc/esi.ts.api.md').split('\n');

/**
 * Every registered domain client, by the name `EsiClientBuilder` and
 * `EsiApiFactory.createClient` take. The list only grows: a new domain client
 * joins it, and none leaves without amending ARCH-14 first.
 */
const REGISTERED: Readonly<Record<ApiClientType, string>> = {
  accessLists: 'AccessListsClient',
  alliance: 'AllianceClient',
  assets: 'AssetsClient',
  calendar: 'CalendarClient',
  characters: 'CharacterClient',
  clones: 'ClonesClient',
  contacts: 'ContactsClient',
  contracts: 'ContractsClient',
  corporationProjects: 'CorporationProjectsClient',
  corporations: 'CorporationsClient',
  cosmetics: 'CosmeticsClient',
  dogma: 'DogmaClient',
  factions: 'FactionClient',
  fittings: 'FittingsClient',
  fleets: 'FleetClient',
  freelanceJobs: 'FreelanceJobsClient',
  incursions: 'IncursionsClient',
  industry: 'IndustryClient',
  insurance: 'InsuranceClient',
  killmails: 'KillmailsClient',
  location: 'LocationClient',
  loyalty: 'LoyaltyClient',
  mail: 'MailClient',
  market: 'MarketClient',
  mercenary: 'MercenaryClient',
  meta: 'MetaClient',
  militaryCampaigns: 'MilitaryCampaignsClient',
  paragonHub: 'ParagonHubClient',
  pi: 'PiClient',
  route: 'RouteClient',
  search: 'SearchClient',
  skills: 'CharacterSkillsClient',
  skyhooks: 'SkyhooksClient',
  sovereignty: 'SovereigntyClient',
  status: 'StatusClient',
  ui: 'UiClient',
  universe: 'UniverseClient',
  wallet: 'WalletClient',
  wars: 'WarsClient',
};
const DOMAIN_CLIENTS = Object.values(REGISTERED);

/** The construction surfaces besides the domain clients, as the report names them. */
const CONSTRUCTION = [
  'EsiClient',
  'getDefaultClient',
  'EsiClientBuilder',
  'CustomEsiClient',
  'EsiApiFactory',
  'EsiApiFactory.createClient',
  'BaseEsiClient',
  'ApiClientType',
];

/** Deprecated since 11.0.0 in favour of `createClient(type)`; they stay tagged. */
const STILL_DEPRECATED = [
  'EsiApiFactory.createAllianceClient',
  'EsiApiFactory.createCharacterClient',
  'EsiApiFactory.createCorporationClient',
  'EsiApiFactory.createMarketClient',
  'EsiApiFactory.createUniverseClient',
  'EsiApiFactory.createFleetClient',
  'EsiApiFactory.createAssetsClient',
  'EsiApiFactory.createWalletClient',
  'EsiApiFactory.createMailClient',
  'EsiTokenManager.createClient',
];

/** The class the root entry exports under `name`. */
function classNamed(name: string): abstract new (...args: never[]) => unknown {
  return (root as unknown as Record<string, unknown>)[name] as abstract new (
    ...args: never[]
  ) => unknown;
}

/** Stops the cache sweep and breaker timers of a domain client's own ApiClient. */
function stopTimers(client: unknown): void {
  const api = (client as { _client?: ApiClient })._client;
  const parts = [api?.getCache(), api?.getCircuitBreaker()] as unknown[];
  for (const part of parts) {
    const stop = (part as { shutdown?: () => void } | null)?.shutdown;
    if (typeof stop === 'function') stop.call(part);
  }
}

const DECLARATION =
  /^(export )?(?:declare )?(?:abstract )?(?:class|interface|type|function|const|enum) (\w+)\b/;

/** The indexes of `name`'s top-level declarations in the report. */
function declarationIndexes(name: string): number[] {
  const found: number[] = [];
  reportLines.forEach((line, i) => {
    const m = DECLARATION.exec(line);
    if (m?.[1] && m[2] === name) found.push(i);
  });
  return found;
}

/** The comment lines directly above line `index`. */
function commentAbove(index: number): string[] {
  const comments: string[] = [];
  for (let i = index - 1; i >= 0; i--) {
    const line = reportLines[i]!.trim();
    if (!line.startsWith('//')) break;
    comments.push(line);
  }
  return comments;
}

/** The index of member `member` inside the class declared at `classIndex`, or -1. */
function memberIndex(classIndex: number, member: string): number {
  const pattern = new RegExp(
    `^\\s+(?:static |protected |abstract )*${member}[(<]`,
  );
  for (let i = classIndex + 1; i < reportLines.length; i++) {
    const line = reportLines[i]!;
    if (line === '}') return -1;
    if (pattern.test(line)) return i;
  }
  return -1;
}

/** Whether `name` (or `Owner.member`) is in the report, and whether every declaration carries `@deprecated`. */
function reportState(name: string): 'missing' | 'untagged' | 'tagged' {
  const [owner, member] = name.split('.') as [string, string | undefined];
  const owners = declarationIndexes(owner);
  if (owners.length === 0) return 'missing';
  const indexes = member
    ? owners.map((o) => memberIndex(o, member)).filter((i) => i >= 0)
    : owners;
  if (indexes.length === 0) return 'missing';
  return indexes.some((i) =>
    commentAbove(i).some((c) => c.includes('@deprecated')),
  )
    ? 'tagged'
    : 'untagged';
}

/** The JSDoc block directly above the first line matching `declaration` in `source`, or ''. */
function jsDocAbove(source: string, declaration: RegExp): string {
  const lines = source.split('\n');
  const at = lines.findIndex((l) => declaration.test(l));
  if (at < 0) return '';
  let i = at - 1;
  if (!lines[i]?.trim().endsWith('*/')) return '';
  const block: string[] = [];
  for (; i >= 0; i--) {
    block.unshift(lines[i]!);
    if (lines[i]!.trim().startsWith('/**')) break;
  }
  return block.join('\n');
}

/** Each source declaration of a construction surface or domain client that carries `@deprecated`. */
function deprecatedInSource(): string[] {
  const found: string[] = [];
  const check = (file: string, label: string, declaration: RegExp): void => {
    if (jsDocAbove(read(file), declaration).includes('@deprecated')) {
      found.push(`${label} (${file})`);
    }
  };
  check('src/EsiClient.ts', 'EsiClient', /^export class EsiClient\b/);
  check(
    'src/EsiClient.ts',
    'getDefaultClient',
    /^export function getDefaultClient\b/,
  );
  check(
    'src/EsiClientBuilder.ts',
    'EsiClientBuilder',
    /^export class EsiClientBuilder\b/,
  );
  check(
    'src/EsiClientBuilder.ts',
    'CustomEsiClient',
    /^export class CustomEsiClient\b/,
  );
  check(
    'src/EsiClientBuilder.ts',
    'EsiApiFactory',
    /^export class EsiApiFactory\b/,
  );
  check(
    'src/EsiClientBuilder.ts',
    'EsiApiFactory.createClient',
    /^\s+static createClient\(/,
  );
  check(
    'src/clients/BaseEsiClient.ts',
    'BaseEsiClient',
    /^export abstract class BaseEsiClient\b/,
  );
  check(
    'src/clients/ClientRegistry.ts',
    'ApiClientType',
    /^export type ApiClientType\b/,
  );
  for (const file of readdirSync(path.join(ROOT, 'src/clients'))) {
    const rel = `src/clients/${file}`;
    const m = /^export class (\w+) extends BaseEsiClient\b/m.exec(read(rel));
    if (m) check(rel, m[1]!, new RegExp(`^export class ${m[1]!}\\b`));
  }
  return found;
}

describe('ARCH-14: the custom clients stay the product', () => {
  it('keeps every construction surface in the API report without @deprecated', () => {
    const wrong = CONSTRUCTION.map((name) => ({
      name,
      state: reportState(name),
    })).filter((r) => r.state !== 'untagged');
    expect(wrong).toEqual([]);
  });

  it('keeps every registered domain client in the report as a class over BaseEsiClient', () => {
    const clients = reportLines
      .map((line) => /^export class (\w+) extends BaseEsiClient\b/.exec(line))
      .filter((m): m is RegExpExecArray => m !== null)
      .map((m) => m[1]!);
    expect(clients).toEqual(expect.arrayContaining(DOMAIN_CLIENTS));
  });

  it('marks no domain client @deprecated in the API report', () => {
    const wrong = DOMAIN_CLIENTS.map((name) => ({
      name,
      state: reportState(name),
    })).filter((r) => r.state !== 'untagged');
    expect(wrong).toEqual([]);
  });

  it('marks no construction surface or domain client @deprecated in source', () => {
    expect(deprecatedInSource()).toEqual([]);
  });

  it('exports every construction surface and domain client from the root entry as itself', () => {
    const exported = root as unknown as Record<string, unknown>;
    const missing = [
      'EsiClient',
      'getDefaultClient',
      'EsiClientBuilder',
      'CustomEsiClient',
      'EsiApiFactory',
      'BaseEsiClient',
      ...DOMAIN_CLIENTS,
    ].filter((name) => typeof exported[name] !== 'function');
    expect(missing).toEqual([]);
    expect(typeof root.EsiApiFactory.createClient).toBe('function');
  });

  it.each(Object.entries(REGISTERED))(
    'registers %s as %s, a BaseEsiClient',
    (type, className) => {
      // A bare ApiClient starts no timers; only the class is compared.
      const apiClient = new ApiClient(
        'identity-test',
        'https://esi.evetech.net',
      );
      const client = createClientInstance(type as ApiClientType, apiClient);
      const expected = (root as unknown as Record<string, unknown>)[
        className
      ] as abstract new (...args: never[]) => unknown;
      expect(client).toBeInstanceOf(expected);
      expect(client).toBeInstanceOf(BaseEsiClient);
    },
  );

  // The registry alone is not enough: each public construction path must
  // hand out the custom class, so a surface rewired to the generated scope
  // tree fails here even when the registry is untouched.
  it.each(Object.entries(REGISTERED))(
    'ARCH-08: EsiApiFactory.createClient(%s) returns a %s',
    (type, className) => {
      const client = root.EsiApiFactory.createClient(type as ApiClientType);
      try {
        expect(client).toBeInstanceOf(classNamed(className));
        expect(client).toBeInstanceOf(BaseEsiClient);
      } finally {
        stopTimers(client);
      }
    },
  );

  it('ARCH-08: EsiClientBuilder builds a CustomEsiClient whose getters return the custom classes', () => {
    const types = Object.keys(REGISTERED) as ApiClientType[];
    const custom = new root.EsiClientBuilder().addClients(types).build();
    try {
      expect(custom).toBeInstanceOf(root.CustomEsiClient);
      const wrong = types.filter((type) => {
        const viaGetter = (custom as unknown as Record<string, unknown>)[type];
        return !(
          viaGetter instanceof classNamed(REGISTERED[type]) &&
          viaGetter instanceof BaseEsiClient &&
          (custom.getClient(type) as unknown) === viaGetter
        );
      });
      expect(wrong).toEqual([]);
    } finally {
      custom.shutdown();
    }
  });

  it("ARCH-08: EsiClient's domain properties return the custom classes", () => {
    const client = new root.EsiClient();
    try {
      const wrong = (Object.keys(REGISTERED) as ApiClientType[]).filter(
        (type) => {
          const domain = (client as unknown as Record<string, unknown>)[type];
          return !(
            domain instanceof classNamed(REGISTERED[type]) &&
            domain instanceof BaseEsiClient
          );
        },
      );
      expect(wrong).toEqual([]);
    } finally {
      client.shutdown();
    }
  });

  it('keeps the 11.0.0 deprecations of the named factories, and only those', () => {
    const states = STILL_DEPRECATED.map((name) => reportState(name));
    expect(states).toEqual(STILL_DEPRECATED.map(() => 'tagged'));
  });

  it('tells a missing name and an untagged one apart', () => {
    // Guards the lookup itself: a typo must not read as untagged.
    expect(reportState('NoSuchExport')).toBe('missing');
    expect(reportState('EsiClient.noSuchMember')).toBe('missing');
    expect(reportState('EsiError')).toBe('untagged');
  });

  it('finds a @deprecated tag in the JSDoc directly above a declaration', () => {
    const source = [
      '/**',
      ' * Old.',
      ' * @deprecated Use the other one.',
      ' */',
      'export class Old {}',
      '',
      '/** New. */',
      'export class New {}',
    ].join('\n');
    expect(jsDocAbove(source, /^export class Old\b/)).toContain('@deprecated');
    expect(jsDocAbove(source, /^export class New\b/)).not.toContain(
      '@deprecated',
    );
    expect(jsDocAbove(source, /^export class Missing\b/)).toBe('');
  });
});
